/* Signature American Sign Language Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Sign-Solarem": "Name-sign concept: sun-handshape at the temple, 'bright mind'.", "Sign-Lunavem": "Name-sign concept: moon-handshape circling, 'night singer'.", "Sign-Terralon": "Name-sign concept: earth-handshape planted, 'grounded keeper'.", "Sign-Aqvamir": "Name-sign concept: water-handshape flowing, 'peaceful flow'.", "Sign-Stellara": "Name-sign concept: star-handshape bursting, 'shining one'.", "Sign-Venturel": "Name-sign concept: wind-handshape rushing, 'swift messenger'.", "House-Solarem": "Signature family-sign concept: house-handshape + sun sign.", "House-Lunavem": "Signature family-sign concept.", "House-Terralon": "Signature family-sign concept.", "House-Aqvamir": "Signature family-sign concept."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Sign-Solarem';
console.log(lookup(q));

